PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/1.2/ref#>
SELECT ?point ?etype ?ts WHERE {
  ?point brick:isPointOf ?e .
  ?e ?etype ?eobj .
  FILTER (str(?e) LIKE "%Chiller02%" || str(?e) LIKE "%HWPump02%" || str(?e) LIKE "%AHU03%" || str(?e) LIKE "%Supply_Fan%")
  OPTIONAL { ?point ref:hasExternalReference ?t . ?t ref:hasTimeseriesId ?ts }
}

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/1.2/ref#>
SELECT ?point ?ts WHERE {
  ?point brick:isPointOf ?e .
  { ?e brick:hasPoint ?point }
  OPTIONAL { ?point ref:hasExternalReference ?t . ?t ref:hasTimeseriesId ?ts }
} FILTER (str(?e) LIKE "%Chiller02%" || str(?e) LIKE "%HWPump02%" || str(?e) LIKE "%AHU03%")

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
