SELECT ?e ?point ?ts WHERE {
  ?point brick:isPointOf ?e .
  OPTIONAL { ?point ref:hasExternalReference ?t . ?t ref:hasTimeseriesId ?ts }
  FILTER (str(?e) LIKE "%Chiller02%" || str(?e) LIKE "%HWPump02%" || str(?e) LIKE "%AHU03%")
}

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
